// checkpointRemoteFetchTimeout bounds checkpoint-remote fetches made from the
// push hot path, where the user's own `git push` is blocked for the duration.
const checkpointRemoteFetchTimeout = 30 * time.Second

func newFetchTmpRef(purpose string) (plumbing.ReferenceName, error) {
	var suffix [12]byte
	if _, err := rand.Read(suffix[:]); err != nil {
		return "", fmt.Errorf("generate temporary fetch ref: %w", err)
	}
	ref := plumbing.ReferenceName(FetchTmpRefPrefix + purpose + "/" + hex.EncodeToString(suffix[:]))
	if err := ref.Validate(); err != nil {
		return "", fmt.Errorf("build temporary fetch ref: %w", err)
	}
	return ref, nil
}

// checkpointRemoteForegroundFetchTimeout bounds checkpoint-remote fetches made
// by user-initiated foreground commands (enable, resume, explain). It matches
// the origin-side metadata fetch budget in the cli package.
//
// Splitting the two fixes a backwards asymmetry: origin-side fetches already had
// two minutes while the checkpoint remote — which by definition holds strictly
// more checkpoint history than origin does — was held to the push hot path's 30
// seconds. A checkpoint archive too large to transfer in 30s was therefore
// unreadable, and each attempt failed the same way with nothing to show for it.
const checkpointRemoteForegroundFetchTimeout = 2 * time.Minute

// pushSettings holds the resolved push configuration from a single settings load.
type pushSettings struct {
	// remote is the git remote name to use for pushing (the user's push remote).
	remote string
	// checkpointURL is the derived URL for pushing checkpoint branches.
	// When set, checkpoint/trails branches are pushed directly to this URL
	// instead of the remote name. Empty means use the remote name.
	checkpointURL string
	// pushDisabled is true if push_sessions is explicitly set to false.
	pushDisabled bool
	// primaryIsRefs records whether the git-refs backend is the configured
	// primary, resolved once here so the pre-push path does not re-read the
	// checkpoints config (LoadCheckpointsConfig is uncached: two whole-file
	// reads and JSON parses per call).
	primaryIsRefs bool
}

// pushTarget returns the target to use for git push/fetch commands for checkpoint branches.
// If a checkpoint URL is configured, returns that; otherwise returns the remote name.
func (ps *pushSettings) pushTarget() string {
	if ps.checkpointURL != "" {
		return ps.checkpointURL
	}
	return ps.remote
}

// hasCheckpointURL returns true if a dedicated checkpoint URL is configured.
func (ps *pushSettings) hasCheckpointURL() bool {
	return ps.checkpointURL != ""
}

// resolvePushSettings loads settings once and returns the resolved push config.
// If a structured checkpoint_remote is configured (e.g., {"provider": "github", "repo": "org/repo"}):
//   - Derives the checkpoint URL from the push remote's protocol (SSH vs HTTPS)
//   - Ignores the setting when it looks inherited from an upstream project rather
//     than configured by this developer, so a fork contributor's checkpoints are
//     not pushed into the upstream's checkpoint repo (see
//     remote.checkpointRemoteIsInherited for how ownership is established)
//   - If a checkpoint branch doesn't exist locally, attempts to fetch it from the URL
//
// The push itself handles failures gracefully (doPushRef warns and continues),
// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:        pushRemoteName,
		pushDisabled:  s.IsPushSessionsDisabled(),
		primaryIsRefs: primaryIsGitRefs(ctx),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	//
	// Skipped entirely under the git-refs primary backend, where the "one-time"
	// framing does not hold: that backend pushes per-checkpoint refs and never
	// writes the local v1 branch (see prePush), so the branch stays missing
	// forever and every single push would re-pay the fetch. On a large checkpoint
	// remote that is a multi-second stall on each `git push` for a branch this
	// push will not touch.
	if !ps.primaryIsRefs {
		if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
			logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
				slog.String("error", err.Error()),
			)
		}
	}

	return ps
}

// FetchMetadataBranch fetches the metadata branch from the checkpoint remote URL
// and updates the local branch. Unlike fetchMetadataBranchIfMissing, this always
// fetches regardless of whether the branch exists locally (for resume scenarios
// where the local branch may be stale).
//
// The fetch is unfiltered (NoFilter: true) because resume needs blob content
// (transcripts, metadata JSON) — not just tree objects, and it runs on the
// foreground budget for the same reason: it is the call that actually moves the
// transcript archive.
func FetchMetadataBranch(ctx context.Context, remoteURL string) error {
	return fetchMetadataBranchWithin(ctx, remoteURL, checkpointRemoteForegroundFetchTimeout)
}

func fetchMetadataBranchWithin(ctx context.Context, remoteURL string, timeout time.Duration) error {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()
	tmpRef, err := newFetchTmpRef("metadata-branch")
	if err != nil {
		return err
	}
	srcRef := refs.Primary.String()

	if err := fetchURLIntoTmpRef(ctx, "", remoteURL, srcRef, tmpRef.String(), "metadata branch", true, timeout); err != nil {
		return err
	}
	if err := PromoteTmpRefSafely(ctx, tmpRef, refs.Primary, branchName); err != nil {
		return err
	}

	return nil
}

// fetchURLIntoTmpRef runs `git fetch <remoteURL> +<srcRef>:<tmpRef>` via the
// checkpoint git wrapper, disabling the terminal prompt so a misconfigured
// credential helper doesn't hang the process. Errors include the redacted URL
// and any captured stderr so operators can diagnose without credentials
// leaking into logs.
//
// When noFilter is true, --filter=blob:none is suppressed even if filtered
// fetches are globally enabled. v1's blobs are the full transcript archive, so
// an unfiltered fetch costs the whole history where a filtered one costs only
// the commit graph — but every caller here passes true, and the reason is worth
// stating because the cheaper option looks safe and is not.
//
// Filtering would be correct only where nothing downstream reads blob content
// from the local branch. No caller meets that bar: each one lands v1 as the
// repo's checkpoint store, and GitStore.List reads each checkpoint's
// metadata.json through a plain tree with no blob fetcher attached. Worse, the
// read path's recovery tier is keyed on the *ref* being missing, so once a
// filtered fetch lands the ref it never fires again — leaving `checkpoint list`
// permanently showing bare IDs with no prompt, date, or counts, recoverable only
// by explaining each checkpoint by ID.
//
// The parameter is kept rather than inlined so the contract stays explicit at
// each call site.
// timeout bounds the fetch: pass checkpointRemoteFetchTimeout on the push hot
// path and checkpointRemoteForegroundFetchTimeout from user-initiated commands.
func fetchURLIntoTmpRef(ctx context.Context, dir, remoteURL, srcRef, tmpRef, label string, noFilter bool, timeout time.Duration) error { //nolint:unparam // every caller needs blob content today; see the doc above for why the filtered variant is unsafe here
	fetchCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	refSpec := fmt.Sprintf("+%s:%s", srcRef, tmpRef)
	output, fetchErr := remote.Fetch(fetchCtx, remote.FetchOptions{
		Remote:   remoteURL,
		RefSpecs: []string{refSpec},
		NoTags:   true,
		NoFilter: noFilter,
		Dir:      dir,
	})
	if fetchErr == nil {
		return nil
	}

	redactedURL := remote.RedactURL(remoteURL)
	msg := strings.TrimSpace(strings.ReplaceAll(string(output), remoteURL, redactedURL))
	if msg != "" {
		return fmt.Errorf("fetch %s from %s failed: %s: %w", label, redactedURL, msg, fetchErr)
	}
	return fmt.Errorf("fetch %s from %s failed: %w", label, redactedURL, fetchErr)
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return plumbing.ZeroHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("resolve ref %s: %w", refName, err)
	}
	return ref.Hash(), nil
}

const opfRewriteFetchPurpose = "opf-rewrite-v1"

// resolveRemoteV1Tip returns the hash of the remote's
// entire/checkpoints/v1 tip.
//
// Fetches the v1 ref from target into a temporary local ref so the
// rewrite compares against the current remote tip rather than a stale
// remote-tracking ref. target may be either a remote name (e.g. "origin")
// or a URL (checkpoint_remote configured). Fetching is especially important
// for URL-based remotes, which have no tracking refs locally; otherwise every
// push would re-redact the entire history as a "bootstrap."
//
// Returns ZeroHash with no error when the remote has no v1 yet (genuine
// bootstrap case). Fetch failures fall back to ZeroHash + a warning
// log; the rewrite then treats the push as bootstrap rather than
// blocking the user on a transient network issue.
func resolveRemoteV1Tip(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	srcRef := "refs/heads/" + paths.MetadataBranchName
	worktreeRoot := ""
	if wt, wtErr := repo.Worktree(); wtErr == nil {
		worktreeRoot = wt.Filesystem().Root()
	}
	tmpRef, err := newFetchTmpRef(opfRewriteFetchPurpose)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	defer func() {
		if err := repo.Storer.RemoveReference(tmpRef); err != nil {
			logging.Debug(ctx, "OPF rewrite: failed to clean up temp ref",
				slog.String("error", err.Error()),
			)
		}
	}()
	if err := fetchURLIntoTmpRef(ctx, worktreeRoot, target, srcRef, tmpRef.String(), "v1 for OPF rewrite", true, checkpointRemoteFetchTimeout); err != nil {
		if !remote.IsURL(target) {
			logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1; using local remote-tracking ref",
				slog.String("remote", target),
				slog.String("error", err.Error()),
			)
			return readV1Tip(repo, plumbing.NewRemoteReferenceName(target, paths.MetadataBranchName))
		}
		logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1 from URL; treating push as bootstrap",
			slog.String("error", err.Error()),
		)
		return plumbing.ZeroHash, nil
	}
	ref, err := repo.Reference(tmpRef, true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return plumbing.ZeroHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("resolve fetched v1 ref: %w", err)
	}
	return ref.Hash(), nil
}

// computeMergeBase returns the merge-base commit hash. Multi-base
// (criss-cross) and unrelated-histories both return ZeroHash —
// caller treats those as diverged.
func computeMergeBase(repo *git.Repository, local, remote plumbing.Hash) (plumbing.Hash, error) {
	lc, err := repo.CommitObject(local)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("load local commit: %w", err)
	}
	rc, err := repo.CommitObject(remote)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("load remote commit: %w", err)
	}
		)
		return fmt.Errorf("push failed: %w", pushErr)
	}
	return errors.New("push failed")
}

// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
func printProtectedRefBlock(w io.Writer, ref, target string) {
	const banner = "[entire] ============================================================"
	displayTarget := displayPushTarget(target)
	fmt.Fprintln(w, banner)
	fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
	fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
	fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
	fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
	fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
	fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
	fmt.Fprintln(w, banner)
}

// fetchAndRebaseRefCommon fetches a remote ref and rebases local commits on top
// of the remote tip. Since checkpoint shards use unique paths, rebases always
// apply cleanly.
// The target can be a remote name or a URL.
func fetchAndRebaseRefCommon(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	return fetchAndRebaseRefWithMetadataThreshold(ctx, target, ref, OversizedCheckpointMetadataThreshold)
}

func fetchAndRebaseRefWithMetadataThreshold(ctx context.Context, target string, ref plumbing.ReferenceName, metadataThreshold int64) error {
	// No timeout: runs under doPushRef's shared budget.
	fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
	if err != nil {
		return fmt.Errorf("resolve fetch target: %w", err)
	}

	// Determine fetch refspec. When the resolved fetch target is a URL or the
	// ref isn't a branch, fetch into a temp ref (no remote-tracking shadow);
	// otherwise use the standard refs/remotes/<remote>/<branch> destination.
	var fetchedRefName plumbing.ReferenceName
	var refSpec string
	usedTempRef := remote.IsURL(fetchTarget) || !ref.IsBranch()
	if usedTempRef {
		fetchedRefName, err = newFetchTmpRef("push-recovery")
		if err != nil {
			return err
		}
		refSpec = fmt.Sprintf("+%s:%s", ref.String(), fetchedRefName)
	} else {
		refSpec = fmt.Sprintf("+%s:refs/remotes/%s/%s", ref.String(), target, ref.Short())
		fetchedRefName = plumbing.NewRemoteReferenceName(target, ref.Short())
	}

	// Use git CLI for fetch (go-git's fetch can be tricky with auth).
	// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
	// shared monorepo), --unshallow downloads the whole repository because
	// git treats shallow as a global property of the clone, not per-ref.
	// The downstream reconcile/rebase paths walk only commits visible past
	// .git/shallow (collectCommitChain / collectCommitsSince), so the
	// missing pre-shallow history isn't needed to produce a correct rebase.
	// Span the fetch separately so a slow sync can be attributed to the network
	// fetch versus the local reconcile/rebase that follows it.
	_, fetchSpan := perf.Start(ctx, "git_fetch")
	fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
	})
	fetchSpan.RecordError(fetchErr)
	fetchSpan.End()
	if fetchErr != nil {
		return fmt.Errorf("fetch failed: %s", fetchOutput)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()
	if usedTempRef {
		defer func() { _ = repo.Storer.RemoveReference(fetchedRefName) }() //nolint:errcheck // cleanup is best-effort
	}
	remoteTip, err := fetchV1TipForMetadataCleanup(ctx, repo, target)
	if err != nil {
		return err
	}
	_, _, err = reconcileOversizedV1ForPush(ctx, repo, localTip, remoteTip, threshold)
	return err
}

func fetchV1TipForMetadataCleanup(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("resolve worktree for checkpoint metadata probe: %w", err)
	}
	ref := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	probeCtx, cancel := context.WithTimeout(ctx, checkpointRemoteFetchTimeout)
	defer cancel()
	out, err := remote.LsRemoteInDir(probeCtx, worktree.Filesystem().Root(), target, ref.String())
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("probe %s on %s: %w", ref, remote.RedactURLOrPath(target), err)
	}
	if len(bytes.TrimSpace(out)) == 0 {
		return plumbing.ZeroHash, nil
	}

	tmpRef, err := newFetchTmpRef(metadataCleanupFetchPurpose)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	if err := fetchURLIntoTmpRef(
		ctx,
		worktree.Filesystem().Root(),
		target,
		ref.String(),
		tmpRef.String(),
		"v1 for metadata cleanup",
		true,
		checkpointRemoteFetchTimeout,
	); err != nil {
		return plumbing.ZeroHash, err
	}
	defer func() {
		_ = repo.Storer.RemoveReference(tmpRef) //nolint:errcheck // cleanup is best-effort
	}()
	fetched, err := repo.Reference(tmpRef, true)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read fetched checkpoint history: %w", err)
	}
	return fetched.Hash(), nil
}

