   201	func oversizedMetadataPathInTree(repo *git.Repository, root plumbing.Hash, threshold int64) (string, error) {
   202		type pendingTree struct {
   203			hash   plumbing.Hash
   204			prefix string
   205		}
   206		stack := []pendingTree{{hash: root}}
   207		seen := make(map[plumbing.Hash]struct{})
   208		for len(stack) > 0 {
   209			last := len(stack) - 1
   210			pending := stack[last]
   211			stack = stack[:last]
   212			if _, ok := seen[pending.hash]; ok {
   213				continue
   214			}
   215			seen[pending.hash] = struct{}{}
   216	
   217			tree, err := repo.TreeObject(pending.hash)
   218			if err != nil {
   219				return "", fmt.Errorf("load tree %s: %w", pending.hash, err)
   220			}
   221			for _, entry := range tree.Entries {
   222				entryPath := entry.Name
   223				if pending.prefix != "" {
   224					entryPath = pending.prefix + "/" + entry.Name
   225				}
   226				if entry.Mode == filemode.Dir {
   227					stack = append(stack, pendingTree{hash: entry.Hash, prefix: entryPath})
   228					continue
   229				}
   230				if path.Base(entryPath) != paths.MetadataFileName || !isFileMode(entry.Mode) {
   231					continue
   232				}
   233				blob, err := repo.BlobObject(entry.Hash)
   234				if err != nil {
   235					return "", fmt.Errorf("load metadata blob %s at %s: %w", entry.Hash, entryPath, err)
   236				}
   237				if blob.Size > threshold {
   238					return entryPath, nil
   239				}
   240			}
   241		}
   242		return "", nil
   243	}
