   397	func firstParentHistory(
   398		ctx context.Context,
   399		repo *git.Repository,
   400		repoPath string,
   401		tip plumbing.Hash,
   402	) ([]*object.Commit, error) {
   403		cmd := exec.CommandContext(ctx, "git", "rev-list", "--first-parent", tip.String())
   404		cmd.Dir = repoPath
   405		output, err := cmd.Output()
   406		if err != nil {
   407			return nil, fmt.Errorf("git rev-list failed: %w", err)
   408		}
   409		hashes := strings.Fields(string(output))
   410		commits := make([]*object.Commit, 0, len(hashes))
   411		for _, value := range hashes {
   412			commit, err := repo.CommitObject(plumbing.NewHash(value))
   413			if err != nil {
   414				return nil, fmt.Errorf("load first-parent commit %s: %w", value, err)
   415			}
   416			commits = append(commits, commit)
   417		}
   418		return commits, nil
   419	}
