   371		}
   372	
   373		rewrittenToOriginal := make(map[plumbing.Hash]plumbing.Hash, len(originalToRewritten))
   374		for oldHash, newHash := range originalToRewritten {
   375			rewrittenToOriginal[newHash] = oldHash
   376		}
   377		localHistory, err := firstParentHistory(ctx, repo, repoPath, rewrittenLocalTip)
   378		if err != nil {
   379			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log rewritten local checkpoint history: %w", err)
