   245	func hasOversizedMetadataIntroducedSince(
   246		ctx context.Context,
   247		repo *git.Repository,
   248		tip, boundary plumbing.Hash,
   249		threshold int64,
   250	) (bool, error) {
   251		repoPath, err := getRepoPath(repo)
   252		if err != nil {
   253			return false, fmt.Errorf("get repository path for metadata scan: %w", err)
   254		}
   255		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   256		defer cancel()
   257	
   258		rangeSpec := tip.String()
   259		if !boundary.IsZero() {
   260			rangeSpec = boundary.String() + ".." + tip.String()
   260			rangeSpec = boundary.String() + ".." + tip.String()
   261		}
   262		objectsCmd := exec.CommandContext(
   263			ctx,
   264			"git", "log", "--root", "--full-history", "-m", "--raw", "--no-renames",
   265			"--diff-filter=AMT", "--format=", "--no-abbrev", "-z", rangeSpec,
   266			"--", ":(glob)**/metadata.json",
   267		)
   268		objectsCmd.Dir = repoPath
   269		stdout, err := objectsCmd.StdoutPipe()
   270		if err != nil {
   271			return false, fmt.Errorf("open checkpoint metadata scan: %w", err)
   272		}
   273		var stderr bytes.Buffer
   274		objectsCmd.Stderr = &stderr
   275		if err := objectsCmd.Start(); err != nil {
   276			return false, fmt.Errorf("start checkpoint metadata scan: %w", err)
   277		}
   278		waited := false
   279		defer func() {
   280			if !waited {
   281				_ = objectsCmd.Process.Kill() //nolint:errcheck // best-effort after a parse/read failure
   282				_ = objectsCmd.Wait()         //nolint:errcheck // reap after best-effort termination
   283			}
   284		}()
   285	
   286		seen := make(map[plumbing.Hash]struct{})
   287		found := false
   288		reader := bufio.NewReader(stdout)
   289		for {
   290			rawRecord, readErr := reader.ReadString(0)
   291			if errors.Is(readErr, io.EOF) && rawRecord == "" {
   292				break
   293			}
   294			if readErr != nil && !errors.Is(readErr, io.EOF) {
   295				return false, fmt.Errorf("read checkpoint metadata scan: %w", readErr)
   296			}
   297			record := strings.TrimSpace(strings.TrimSuffix(rawRecord, "\x00"))
   298			if record == "" {
   299				if errors.Is(readErr, io.EOF) {
   300					break
   301				}
   302				continue
   303			}
   304			if !strings.HasPrefix(record, ":") {
   305				return false, fmt.Errorf("parse checkpoint metadata scan record %q", record)
   306			}
   307			pathField, pathErr := reader.ReadString(0)
   308			if pathErr != nil && !errors.Is(pathErr, io.EOF) {
   309				return false, fmt.Errorf("read checkpoint metadata path: %w", pathErr)
   310			}
   311			metadataPath := strings.TrimSuffix(pathField, "\x00")
   312			if path.Base(metadataPath) != paths.MetadataFileName {
   313				return false, fmt.Errorf("unexpected checkpoint metadata path %q", metadataPath)
   314			}
   315	
   316			if err := ctx.Err(); err != nil {
   317				return false, fmt.Errorf("scan local checkpoint metadata: %w", err)
   318			}
   319			fields := strings.Fields(record)
   320			if len(fields) < 5 {
   321				return false, fmt.Errorf("parse checkpoint metadata scan record %q", record)
   322			}
   323			mode, err := strconv.ParseUint(fields[1], 8, 32)
   324			if err != nil {
   325				return false, fmt.Errorf("parse checkpoint metadata mode %q: %w", fields[1], err)
   326			}
   327			if !isFileMode(filemode.FileMode(mode)) || found {
   328				continue
   329			}
   330			hash := plumbing.NewHash(fields[3])
   331			if _, exists := seen[hash]; exists {
   332				continue
   333			}
   334			seen[hash] = struct{}{}
   335			blob, err := repo.BlobObject(hash)
   336			if err != nil {
   337				return false, fmt.Errorf("load metadata blob %s at %s: %w", hash, metadataPath, err)
   338			}
   339			if blob.Size > threshold {
   340				found = true
   341			}
   342			if errors.Is(readErr, io.EOF) {
   343				break
   344			}
   345		}
   346		if err := objectsCmd.Wait(); err != nil {
   347			waited = true
   348			return false, fmt.Errorf("list local checkpoint metadata objects: %s: %w", strings.TrimSpace(stderr.String()), err)
   349		}
   350		waited = true
   351		return found, nil
   352	}
