   354	func findSharedRewrittenTree(
   355		ctx context.Context,
   356		repo *git.Repository,
   357		repoPath string,
   358		rewrittenLocalTip, remoteTip plumbing.Hash,
   359		originalToRewritten map[plumbing.Hash]plumbing.Hash,
   360	) (rewritten, original plumbing.Hash, found bool, err error) {
   361		remoteTrees := make(map[plumbing.Hash]struct{})
   362		remoteHistory, err := firstParentHistory(ctx, repo, repoPath, remoteTip)
   363		if err != nil {
   364			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log remote checkpoint history: %w", err)
   365		}
   366		for _, commit := range remoteHistory {
   367			if err := ctx.Err(); err != nil {
   368				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("scan remote checkpoint trees: %w", err)
   369			}
   370			remoteTrees[commit.TreeHash] = struct{}{}
   371		}
   372	
   373		rewrittenToOriginal := make(map[plumbing.Hash]plumbing.Hash, len(originalToRewritten))
   374		for oldHash, newHash := range originalToRewritten {
   375			rewrittenToOriginal[newHash] = oldHash
   376		}
   377		localHistory, err := firstParentHistory(ctx, repo, repoPath, rewrittenLocalTip)
   378		if err != nil {
   379			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log rewritten local checkpoint history: %w", err)
   380		}
   381		for _, commit := range localHistory {
   382			if err := ctx.Err(); err != nil {
   383				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("scan rewritten local checkpoint trees: %w", err)
   384			}
   385			if _, exists := remoteTrees[commit.TreeHash]; !exists {
   386				continue
   387			}
   388			oldHash, exists := rewrittenToOriginal[commit.Hash]
   389			if !exists {
   390				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("rewritten commit %s has no original", commit.Hash)
   391			}
   392			return commit.Hash, oldHash, true, nil
   393		}
   394		return plumbing.ZeroHash, plumbing.ZeroHash, false, nil
   395	}
